/**
 * A tournament worth screenshotting.
 *
 * `seed.ts` creates the organization and the ladder — the minimum for the app
 * to boot. This creates what a tournament actually looks like mid-event: real
 * draws generated by the engine, scores entered, winners advanced, one match
 * live, courts allotted, and three published updates with photographs.
 *
 *   pnpm --filter @opentennis/db exec tsx src/seed-demo.ts
 *
 * DEVELOPMENT ONLY. It refuses to run against the production branch — see
 * `assertNotProduction`. Local development pointed at production until
 * 2026-11-06 and a session of ordinary testing wrote scores into the live
 * database; this script writes far more than that.
 *
 * Idempotent by deletion: it drops its own tournament and its own updates by
 * slug and rebuilds them. It never touches Copa Otoño, Invierno, or any
 * player row it did not create — players are matched by email and reused.
 *
 * Images come from `scripts/make-demo-images.mjs` and must exist under
 * apps/web/public/demo/ or the covers render as broken.
 */

import { and, eq, inArray } from 'drizzle-orm';
import { generateRoundRobin, generateSingleElimination } from '@opentennis/engine';
import { createDb, type Database } from './client';
import { loadEntrantsForEngine, persistDraw } from './persist-draw';
import {
  categories,
  courts,
  entrantPlayers,
  entrants,
  events,
  matches,
  matchSides,
  mediaItems,
  organizations,
  players,
  rounds,
  sets,
  stages,
  tournaments,
  updates,
} from './schema';

const TOURNAMENT_SLUG = 'copa-aniversario-open-tennis-26';
const UPDATE_SLUGS = [
  'copa-aniversario-cuadros-publicados',
  'copa-aniversario-inscripciones-abiertas',
  'copa-aniversario-finales-domingo',
];

/**
 * The production compute endpoint, from CLAUDE.md. Matching on the endpoint id
 * rather than the whole host is deliberate: the pooled and direct URLs differ
 * by a `-pooler` suffix and both must be caught.
 */
const PRODUCTION_ENDPOINT = 'ep-rapid-dawn-akcv4lkp';

function assertNotProduction(connectionString: string): void {
  if (process.env['ALLOW_DEMO_SEED_ON_PROD'] === '1') {
    console.warn('! ALLOW_DEMO_SEED_ON_PROD=1 — writing demo data to production.');
    return;
  }
  let host: string;
  try {
    host = new URL(connectionString).host;
  } catch {
    // An unparseable URL is an unknown target, and an unknown target is
    // treated as production.
    throw new Error('DATABASE_URL could not be parsed; refusing to seed.');
  }
  if (host.includes(PRODUCTION_ENDPOINT)) {
    throw new Error(
      `Refusing to seed demo data into production (${host}).\n` +
        'Point DATABASE_URL at the development branch. Override with ' +
        'ALLOW_DEMO_SEED_ON_PROD=1 only if you mean it.',
    );
  }
  console.log(`· target ${host}`);
}

/* -------------------------------------------------------------------------- */
/* Cast                                                                       */
/* -------------------------------------------------------------------------- */

/** Mexican names, spelled properly. Accents are part of the test. */
const CAST: ReadonlyArray<readonly [string, string]> = [
  ['Diego', 'Ramírez'], ['Lucía', 'Fernández'], ['Mateo', 'Castillo'],
  ['Valeria', 'Ibarra'], ['Santiago', 'Beltrán'], ['Renata', 'Ocampo'],
  ['Emiliano', 'Vargas'], ['Camila', 'Zepeda'], ['Sebastián', 'Padilla'],
  ['Regina', 'Lozano'], ['Andrés', 'Quintero'], ['Ximena', 'Carrillo'],
  ['Joaquín', 'Mendoza'], ['Fernanda', 'Rosales'], ['Patricio', 'Esquivel'],
  ['Mariana', 'Villalobos'], ['Rodrigo', 'Arellano'], ['Daniela', 'Narváez'],
  ['Tomás', 'Guerrero'], ['Paulina', 'Cervantes'], ['Ignacio', 'Barrera'],
  ['Alejandra', 'Montoya'], ['Leonardo', 'Sandoval'], ['Isabela', 'Rivas'],
  ['Maximiliano', 'Treviño'], ['Sofía', 'Delgado'], ['Gael', 'Aguirre'],
  ['Natalia', 'Pacheco'], ['Bruno', 'Salcedo'], ['Victoria', 'Lerma'],
  ['Héctor', 'Jiménez'], ['Carolina', 'Bustos'], ['Álvaro', 'Figueroa'],
  ['Elena', 'Murillo'], ['Nicolás', 'Alcaraz'], ['Jimena', 'Peralta'],
  ['Ramón', 'Escobedo'], ['Lorena', 'Cisneros'], ['Óscar', 'Valenzuela'],
  ['Adriana', 'Rentería'],
];

const CLUBS = ['Open Tennis', 'Club Campestre', 'Deportivo Hidalgo', null];

const slugEmail = (first: string, last: string): string =>
  `${first}.${last}`
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z.]/g, '') + '@demo.opentennis.mx';

/* -------------------------------------------------------------------------- */
/* Deterministic pseudo-randomness                                            */
/* -------------------------------------------------------------------------- */

/** Mulberry32. Same seed, same tournament, every run. */
function rng(seed: number): () => number {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A plausible best-of-three scoreline, weighted towards two sets. */
function scoreline(rand: () => number): Array<[number, number]> {
  const straight = rand() < 0.68;
  const set = (): [number, number] => {
    const r = rand();
    if (r < 0.18) return [7, 5];
    if (r < 0.32) return [7, 6];
    if (r < 0.62) return [6, 4];
    if (r < 0.85) return [6, 3];
    return [6, 2];
  };
  const a = set();
  const b = set();
  if (straight) return [a, b];
  // Loser takes the second; a third decides it.
  return [a, [b[1], b[0]], set()];
}

/* -------------------------------------------------------------------------- */
/* Seed                                                                       */
/* -------------------------------------------------------------------------- */

interface EventSpec {
  readonly categoryCode: string;
  readonly discipline: 'singles' | 'doubles';
  readonly format: 'singleElimination' | 'roundRobin';
  readonly entrantCount: number;
  /** How much of the draw has been played. */
  readonly progress: 'complete' | 'underway' | 'notStarted';
}

const EVENT_PLAN: readonly EventSpec[] = [
  // Stronger categories run round robins because few people enter.
  { categoryCode: 'Open', discipline: 'singles', format: 'roundRobin', entrantCount: 6, progress: 'underway' },
  { categoryCode: 'A', discipline: 'singles', format: 'singleElimination', entrantCount: 8, progress: 'underway' },
  { categoryCode: 'B', discipline: 'singles', format: 'singleElimination', entrantCount: 16, progress: 'complete' },
  { categoryCode: 'C+', discipline: 'doubles', format: 'singleElimination', entrantCount: 8, progress: 'underway' },
  { categoryCode: 'C', discipline: 'singles', format: 'singleElimination', entrantCount: 8, progress: 'notStarted' },
];

async function findOrCreatePlayers(
  db: Database,
  organizationId: string,
  count: number,
): Promise<string[]> {
  const ids: string[] = [];
  for (let i = 0; i < count; i += 1) {
    const entry = CAST[i % CAST.length];
    if (entry === undefined) throw new Error('cast exhausted');
    const [first, last] = entry;
    // A second pass round the cast would collide on email, so suffix it.
    const suffix = i >= CAST.length ? String(Math.floor(i / CAST.length) + 1) : '';
    const email = suffix === '' ? slugEmail(first, last) : slugEmail(first, last + suffix);
    const existing = await db
      .select({ id: players.id })
      .from(players)
      .where(and(eq(players.organizationId, organizationId), eq(players.email, email)))
      .limit(1);
    const found = existing[0];
    if (found !== undefined) {
      ids.push(found.id);
      continue;
    }
    const inserted = await db
      .insert(players)
      .values({
        organizationId,
        firstName: first,
        lastName: suffix === '' ? last : `${last} ${suffix}`,
        email,
        phone: `+52 664 ${String(100 + i).padStart(3, '0')} ${String(1000 + i * 7).slice(0, 4)}`,
        clubAffiliation: CLUBS[i % CLUBS.length] ?? null,
      })
      .returning({ id: players.id });
    const row = inserted[0];
    if (row === undefined) throw new Error('player insert returned nothing');
    ids.push(row.id);
  }
  return ids;
}

export async function seedDemo(connectionString: string): Promise<void> {
  assertNotProduction(connectionString);
  const db = createDb(connectionString);

  const org = (await db.select().from(organizations).limit(1))[0];
  if (org === undefined) throw new Error('No organization. Run seed.ts first.');
  const organizationId = org.id;

  // --- clean out a previous run -------------------------------------------
  const prior = await db
    .select({ id: tournaments.id })
    .from(tournaments)
    .where(eq(tournaments.slug, TOURNAMENT_SLUG));
  for (const t of prior) {
    // Cascades take events, entrants, stages, rounds, matches, sides, sets.
    await db.delete(tournaments).where(eq(tournaments.id, t.id));
  }
  await db.delete(updates).where(inArray(updates.slug, [...UPDATE_SLUGS]));

  // --- tournament ----------------------------------------------------------
  const today = new Date();
  const iso = (offsetDays: number): string => {
    const d = new Date(today);
    d.setUTCDate(d.getUTCDate() + offsetDays);
    return d.toISOString().slice(0, 10);
  };

  const tournamentRow = (
    await db
      .insert(tournaments)
      .values({
        organizationId,
        name: 'Copa Aniversario Open Tennis',
        slug: TOURNAMENT_SLUG,
        venue: 'Open Tennis, Tijuana',
        timezone: 'America/Tijuana',
        startDate: iso(-1),
        endDate: iso(1),
        status: 'inProgress',
        visibility: 'public',
        entriesOpen: false,
      })
      .returning({ id: tournaments.id })
  )[0];
  if (tournamentRow === undefined) throw new Error('tournament insert failed');
  const tournamentId = tournamentRow.id;

  // --- courts --------------------------------------------------------------
  const courtIds: string[] = [];
  for (let i = 1; i <= 4; i += 1) {
    const c = (
      await db
        .insert(courts)
        .values({ organizationId, tournamentId, name: `Cancha ${i}`, sortOrder: i })
        .returning({ id: courts.id })
    )[0];
    if (c === undefined) throw new Error('court insert failed');
    courtIds.push(c.id);
  }

  // --- cast ----------------------------------------------------------------
  const totalPlayers = EVENT_PLAN.reduce(
    (n, e) => n + e.entrantCount * (e.discipline === 'doubles' ? 2 : 1),
    0,
  );
  const playerIds = await findOrCreatePlayers(db, organizationId, totalPlayers);
  let playerCursor = 0;

  const ladder = await db
    .select({ id: categories.id, code: categories.code })
    .from(categories)
    .where(eq(categories.organizationId, organizationId));
  const categoryByCode = new Map(ladder.map((c) => [c.code, c.id]));

  const rand = rng(20261108);
  let liveAssigned = false;
  let scheduleSlot = 0;

  for (const spec of EVENT_PLAN) {
    const categoryId = categoryByCode.get(spec.categoryCode);
    if (categoryId === undefined) {
      console.warn(`  skip ${spec.categoryCode}: not in the ladder`);
      continue;
    }

    const eventRow = (
      await db
        .insert(events)
        .values({
          organizationId,
          tournamentId,
          categoryId,
          discipline: spec.discipline,
          format: spec.format,
          status: spec.progress === 'notStarted' ? 'published' : 'inProgress',
          // The Open draw costs more, as it does at the club.
          entryFeeCents: spec.categoryCode === 'Open' ? 45000 : 30000,
          drawRandomSeed: `demo-${spec.categoryCode}-${spec.discipline}`,
        })
        .returning({ id: events.id })
    )[0];
    if (eventRow === undefined) throw new Error('event insert failed');
    const eventId = eventRow.id;

    // --- entrants ----------------------------------------------------------
    for (let i = 0; i < spec.entrantCount; i += 1) {
      const e = (
        await db
          .insert(entrants)
          .values({
            organizationId,
            eventId,
            // Seed the top two only; most of the field is unseeded, which is
            // how these draws actually arrive.
            seed: i < 2 ? i + 1 : null,
            status: 'active',
            paid: rand() < 0.8,
            paidAt: rand() < 0.8 ? new Date() : null,
            sourceLabel: ['poster', 'desk', 'instagram'][i % 3] ?? null,
          })
          .returning({ id: entrants.id })
      )[0];
      if (e === undefined) throw new Error('entrant insert failed');

      const per = spec.discipline === 'doubles' ? 2 : 1;
      for (let p = 0; p < per; p += 1) {
        const playerId = playerIds[playerCursor];
        playerCursor += 1;
        if (playerId === undefined) throw new Error('ran out of players');
        await db
          .insert(entrantPlayers)
          .values({ entrantId: e.id, playerId, position: p });
      }
    }

    // --- draw --------------------------------------------------------------
    const engineEntrants = await loadEntrantsForEngine(db, organizationId, eventId);
    const stage =
      spec.format === 'roundRobin'
        ? generateRoundRobin({ entrants: engineEntrants, randomSeed: `demo-${spec.categoryCode}` })
        : generateSingleElimination({
            entrants: engineEntrants,
            randomSeed: `demo-${spec.categoryCode}`,
          });

    await persistDraw({
      db,
      organizationId,
      tournamentId,
      eventId,
      stage,
      entrantIdMap: new Map(engineEntrants.map((e) => [e.id, e.id])),
    });

    console.log(
      `  ${spec.categoryCode} ${spec.discipline}`.padEnd(22) +
        `${spec.format === 'roundRobin' ? 'round robin' : 'bracket'}, ` +
        `${spec.entrantCount} entrants, ${spec.progress}`,
    );

    if (spec.progress === 'notStarted') continue;

    // --- play it -----------------------------------------------------------
    const roundRows = await db
      .select({ id: rounds.id, index: rounds.roundIndex })
      .from(rounds)
      .where(eq(rounds.stageId, (await stageIdFor(db, eventId)) ?? ''))
      .orderBy(rounds.roundIndex);

    const total = roundRows.length;
    // "underway" stops short of the last round so there is something to play.
    const playThrough = spec.progress === 'complete' ? total : Math.max(1, total - 1);

    for (let r = 0; r < playThrough; r += 1) {
      const round = roundRows[r];
      if (round === undefined) continue;
      const roundMatches = await db
        .select({ id: matches.id, engineMatchId: matches.engineMatchId, status: matches.status })
        .from(matches)
        .where(eq(matches.roundId, round.id))
        .orderBy(matches.slotIndex);

      for (const m of roundMatches) {
        if (m.status === 'bye') continue;
        const sideRows = await db
          .select({ id: matchSides.id, position: matchSides.position, entrantId: matchSides.entrantId })
          .from(matchSides)
          .where(eq(matchSides.matchId, m.id))
          .orderBy(matchSides.position);
        const [s0, s1] = sideRows;
        if (s0?.entrantId == null || s1?.entrantId == null) continue;

        // Exactly one match is left live, for the optic-yellow state.
        const makeLive = !liveAssigned && spec.progress === 'underway' && r === playThrough - 1;
        if (makeLive) {
          liveAssigned = true;
          await db
            .update(matches)
            .set({
              status: 'live',
              startedAt: new Date(Date.now() - 40 * 60 * 1000),
              courtId: courtIds[0] ?? null,
              scheduledAt: new Date(Date.now() - 45 * 60 * 1000),
            })
            .where(eq(matches.id, m.id));
          // One set in the bag, so the live score has something to show.
          await db.insert(sets).values({
            matchId: m.id,
            setIndex: 0,
            side0Games: 6,
            side1Games: 4,
          });
          continue;
        }

        const winnerFirst = rand() < 0.5;
        const winnerEntrantId = winnerFirst ? s0.entrantId : s1.entrantId;
        const games = scoreline(rand);
        scheduleSlot += 1;
        const when = new Date(Date.now() - (roundRows.length - r) * 3 * 3600 * 1000);

        await db
          .update(matches)
          .set({
            status: 'complete',
            outcome: 'completed',
            winnerEntrantId,
            completedAt: when,
            scheduledAt: when,
            courtId: courtIds[scheduleSlot % courtIds.length] ?? null,
          })
          .where(eq(matches.id, m.id));

        for (const [i, [a, b]] of games.entries()) {
          await db.insert(sets).values({
            matchId: m.id,
            setIndex: i,
            side0Games: winnerFirst ? a : b,
            side1Games: winnerFirst ? b : a,
            ...(a === 7 && b === 6 ? { side0TiebreakPoints: winnerFirst ? 7 : 5, side1TiebreakPoints: winnerFirst ? 5 : 7 } : {}),
          });
        }

        // Advance: whatever side was waiting on this match now has a name.
        await db
          .update(matchSides)
          .set({ entrantId: winnerEntrantId })
          .where(
            and(
              eq(matchSides.sourceKind, 'winnerOf'),
              eq(matchSides.sourceMatchId, m.engineMatchId),
            ),
          );
      }
    }

  }

  // --- updates and photographs ---------------------------------------------
  const posts = [
    {
      slug: UPDATE_SLUGS[0] as string,
      title: 'Cuadros publicados',
      excerpt: 'Ya están los cuadros de todas las categorías. Revisa tu horario antes de llegar.',
      body: 'Los cuadros de la Copa Aniversario ya están publicados.\n\nCada categoría tiene su propio formato: Open se juega en round robin por el número de inscritos, y el resto en eliminación directa. Revisa el orden de juego el mismo día, porque las canchas se reasignan si un partido se alarga.',
      cover: '/demo/cover-draws-posted.png',
      coverAlt: 'Diagrama de un cuadro de eliminación directa',
      days: -2,
    },
    {
      slug: UPDATE_SLUGS[1] as string,
      title: 'Inscripciones abiertas',
      excerpt: 'Quedan lugares en C y C+. La inscripción se cierra el viernes a mediodía.',
      body: 'Siguen abiertas las inscripciones para la Copa Aniversario.\n\nEscanea el código en el club o pasa a la recepción. El pago se hace en el mostrador; no hace falta registrar una tarjeta.',
      cover: '/demo/cover-entries-open.png',
      coverAlt: 'Línea de fondo de una cancha con una pelota',
      days: -9,
    },
    {
      slug: UPDATE_SLUGS[2] as string,
      title: 'Finales el domingo',
      excerpt: 'Las finales de todas las categorías se juegan el domingo a partir de las 10:00.',
      body: 'Las finales se juegan el domingo.\n\nEmpezamos a las 10:00 en Cancha 1 con C+ dobles, y seguimos con A y B singles. La premiación es al terminar la última final.',
      cover: '/demo/cover-finals.png',
      coverAlt: 'Cancha de tenis vista desde arriba',
      days: 0,
    },
  ];

  const gallery = [
    ['/demo/gallery-court-1.png', 'Cancha 1 vista desde arriba', 'Cancha 1, sábado por la mañana'],
    ['/demo/gallery-court-2.png', 'Cancha vista desde arriba', 'Cancha 3 antes del primer partido'],
    ['/demo/gallery-court-3.png', 'Cancha de superficie dura', 'Cancha 4'],
    ['/demo/gallery-baseline.png', 'Línea de fondo', 'Detalle de la línea de fondo'],
    ['/demo/gallery-baseline-2.png', 'Esquina de la cancha', 'Esquina de Cancha 2'],
    ['/demo/gallery-surface.png', 'Superficie de la cancha con una pelota', 'Pelota en juego'],
  ] as const;

  let galleryCursor = 0;
  for (const post of posts) {
    const publishedAt = new Date(today);
    publishedAt.setUTCDate(publishedAt.getUTCDate() + post.days);
    const row = (
      await db
        .insert(updates)
        .values({
          organizationId,
          slug: post.slug,
          title: post.title,
          excerpt: post.excerpt,
          body: post.body,
          coverUrl: post.cover,
          coverAlt: post.coverAlt,
          tournamentId,
          visibility: 'public',
          publishedAt,
        })
        .returning({ id: updates.id })
    )[0];
    if (row === undefined) throw new Error('update insert failed');

    // Two photographs each, so the media page has a real grid.
    for (let i = 0; i < 2; i += 1) {
      const item = gallery[galleryCursor % gallery.length];
      galleryCursor += 1;
      if (item === undefined) continue;
      const [url, alt, caption] = item;
      await db.insert(mediaItems).values({
        organizationId,
        updateId: row.id,
        url,
        alt,
        caption,
        position: i,
      });
    }
  }

  console.log(`\n  ${posts.length} updates, ${galleryCursor} photographs`);
  console.log(`\n✓ /t/${TOURNAMENT_SLUG}`);
}

/** The main stage of an event. Consolation stages carry a parent, so exclude them. */
async function stageIdFor(db: Database, eventId: string): Promise<string | undefined> {
  const rows = await db
    .select({ id: stages.id })
    .from(stages)
    .where(eq(stages.eventId, eventId))
    .orderBy(stages.sortOrder);
  return rows[0]?.id;
}

const url = process.env['DATABASE_URL'];
if (url === undefined || url === '') {
  console.error('DATABASE_URL is not set.');
  process.exit(1);
}
await seedDemo(url);
process.exit(0);
